// SetMemberRole changes a member's role. An organization's only owner cannot be given another role (ErrLastOwner).
func (s *Store) SetMemberRole(orgID, userID string, role Role) (Member, error) {
	if !role.Valid() {
		return Member{}, invalid("unknown role %q", role)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	k := memberKey{orgID, userID}
	m, ok := s.members[k]
	if !ok {
		return Member{}, ErrNotFound
	}
	if m.Role == RoleOwner && role != RoleOwner && s.owners(orgID) == 1 {
		return Member{}, ErrLastOwner
	}
	m.Role = role
	s.members[k] = m
	return m, nil
}

