// updateMember changes another member's role. Nobody changes their own role, except that an owner
// may demote themselves when they are not the only owner; the only owner gets 409 last_owner.
func (s *Server) updateMember(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	target := r.PathValue("user_id")
	self := target == p.UserID
	if self && p.Role != store.RoleOwner {
		writeError(w, http.StatusForbidden, "forbidden", "nobody changes their own role")
		return
	}
	if !auth.CanManageTeam(p.Role) {
		writeError(w, http.StatusForbidden, "forbidden", "only owners and admins manage members")
		return
	}
	var in struct {
		Role store.Role `json:"role"`
	}
	if !decode(w, r, &in) {
		return
	}
	if self {
		if in.Role == store.RoleOwner || s.hasCoOwner(p.OrgID, p.UserID) {
			writeError(w, http.StatusForbidden, "forbidden", "nobody changes their own role")
			return
		}
	} else if !s.mayManageMember(w, p, target, in.Role) {
		return
	}

